package co.pereira.cultura;

import java.math.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static co.pereira.cultura.AuthService.require;
import static co.pereira.cultura.AuthService.role;

/** The resource descriptors are a fixed whitelist; no client text becomes a SQL identifier. */
@Service
public class RecordsService {
    record Resource(String path,String table,String module,String report,String document,List<String> fields,Set<String> required,Set<String> filters) {}
    private static Resource r(String path,String table,String module,String report,String document,String fields,String required,String filters){return new Resource(path,table,module,report,document,List.of(fields.split(" ")),Set.of(required.split(" ")),Set.of(filters.split(" ")));}
    static final List<Resource> RESOURCES=List.of(
        r("/peticiones","peticiones","peticiones","peticiones","peticion","fecha_ingreso numero_radicado peticionario solicitud tipo_peticion plazo_habil asignado_a fecha_vencimiento estado fecha_respuesta","fecha_ingreso numero_radicado peticionario solicitud tipo_peticion estado","estado asignado_a"),
        r("/cajas-menores","cajas_menores","caja_menor","cajas-menores","caja_menor","vigencia resolucion valor_fondo sobrante_consignado","vigencia valor_fondo","estado vigencia"),
        r("/gastos-caja-menor","gastos_caja_menor","caja_menor","gastos-caja-menor","gasto","caja_id fecha concepto valor numero_recibo autorizado_por estado_revision observacion_revision","caja_id fecha concepto valor estado_revision","caja_id estado_revision"),
        r("/reintegros-caja-menor","reintegros_caja_menor","caja_menor","reintegros-caja-menor","reintegro","caja_id fecha valor referencia responsable observaciones","caja_id fecha valor referencia responsable","caja_id"),
        r("/presupuesto/solicitudes","solicitudes_presupuestales","presupuesto","solicitudes-presupuestales","presupuesto","tipo numero descripcion valor fecha estado referencia_siif responsable observaciones","tipo descripcion fecha estado","tipo estado"),
        r("/presupuesto/descuentos","descuentos","presupuesto","descuentos",null,"orden_id tipo valor","orden_id tipo valor","orden_id tipo"),
        r("/convenios","convenios","convenios","convenios","convenio","numero fecha_inicio nit entidad valor_total secretaria_responsable","numero fecha_inicio nit entidad valor_total secretaria_responsable","estado nit"));
    static final Map<String,Object> DEFAULTS=Map.of("tipo_peticion","general","estado_revision","pendiente","secretaria_responsable","Secretaría de Cultura");
    static final List<String> ETAPAS=List.of("apertura","compras","relacion_gastos","revision_juridica","firma","control_interno","reintegro","cierre");
    static final Set<String> PET_STATES=Set.of("recibida","distribuida","en_tramite","respondida"), PET_TYPES=Set.of("general","informacion_documentos","consulta","otro"), REV_STATES=Set.of("pendiente","aprobado","rechazado"), BUDGET_TYPES=Set.of("certificado_conveniencia","certificado_disponibilidad","compromiso","orden_pago","informe_ejecucion","informe_pago","modificacion_presupuestal"), BUDGET_STATES=Set.of("solicitada","aprobada","rechazada","tramitada"), DISCOUNT_TYPES=Set.of("retencion_fuente","sobretasa_deporte","estampilla_procultura","industria_comercio","estampilla_prodesarrollo");
    static final Map<String,Integer> PLAZOS=Map.of("general",15,"informacion_documentos",10,"consulta",30);
    static final Map<String,Integer> MAX=Map.ofEntries(Map.entry("numero_radicado",50),Map.entry("numero",50),Map.entry("peticionario",200),Map.entry("asignado_a",150),Map.entry("resolucion",100),Map.entry("concepto",300),Map.entry("numero_recibo",50),Map.entry("autorizado_por",150),Map.entry("responsable",150),Map.entry("referencia",150),Map.entry("referencia_siif",100),Map.entry("nit",30),Map.entry("entidad",200),Map.entry("secretaria_responsable",150),Map.entry("tipo",30),Map.entry("tipo_peticion",25),Map.entry("estado",25),Map.entry("estado_revision",15));
    private final JdbcTemplate db;
    private final AuthService auth;
    public RecordsService(JdbcTemplate db,AuthService auth){this.db=db;this.auth=auth;}
    static Resource resource(String path){return RESOURCES.stream().filter(r->r.path.equals(path)).findFirst().orElseThrow(ApiFailure::missing);}
    static Resource byDocument(String entity){return RESOURCES.stream().filter(r->Objects.equals(r.document,entity)).findFirst().orElseThrow(()->ApiFailure.bad("Entidad documental inválida"));}
    static Resource byReport(String report){return RESOURCES.stream().filter(r->r.report.equals(report)).findFirst().orElseThrow(ApiFailure::missing);}
    Map<String,Object> find(Resource r,long id,boolean lock){return db.queryForList("SELECT * FROM "+r.table+" WHERE id=?"+(lock?" FOR UPDATE":""),id).stream().findFirst().orElseThrow(ApiFailure::missing);}
    static String text(Object o){return o==null?null:o.toString();}
    static long id(Object o){return ((Number)o).longValue();}
    static LocalDate date(Object o){if(o==null)return null;if(o instanceof LocalDate d)return d;if(o instanceof java.sql.Date d)return d.toLocalDate();try{return LocalDate.parse(o.toString());}catch(Exception e){throw ApiFailure.bad("Fecha inválida; utilice AAAA-MM-DD");}}
    static BigDecimal money(Object o){if(o==null)return null;try{BigDecimal n=new BigDecimal(o.toString()).setScale(2,RoundingMode.UNNECESSARY);if(n.precision()>15)throw new ArithmeticException();return n;}catch(Exception e){throw ApiFailure.bad("Importe inválido: máximo 13 enteros y 2 decimales");}}
    static BigDecimal zero(Object o){return o==null?BigDecimal.ZERO:money(o);}
    static int integer(Object o,int min,int max){try{int i=new BigDecimal(o.toString()).intValueExact();if(i<min||i>max)throw new ArithmeticException();return i;}catch(Exception e){throw ApiFailure.bad("Número entero fuera de rango");}}
    static long identifier(Object o){try{long i=new BigDecimal(o.toString()).longValueExact();if(i<1)throw new ArithmeticException();return i;}catch(Exception e){throw ApiFailure.bad("Identificador inválido");}}
    static void choice(Map<String,Object> d,String k,Set<String> values){if(!values.contains(text(d.get(k))))throw ApiFailure.bad("Valor inválido para "+k);}
    static boolean eq(Object a,Object b){if(a==null||b==null)return a==b;if(a instanceof BigDecimal||b instanceof BigDecimal)return money(a).compareTo(money(b))==0;if(a instanceof Number&&b instanceof Number)return new BigDecimal(a.toString()).compareTo(new BigDecimal(b.toString()))==0;if(a instanceof LocalDate||b instanceof LocalDate||a instanceof java.sql.Date||b instanceof java.sql.Date)return date(a).equals(date(b));return Objects.equals(a,b);}
    private Object normalize(String field,Object value){
        if(value==null||value instanceof String s&&s.isBlank())return null;
        if(field.startsWith("fecha"))return date(value);
        if(Set.of("caja_id","orden_id").contains(field))return identifier(value);
        if(field.equals("vigencia"))return integer(value,2000,2100);
        if(field.equals("plazo_habil"))return integer(value,1,365);
        if(Set.of("valor","valor_total","valor_fondo","sobrante_consignado").contains(field))return money(value);
        if(!(value instanceof String s))throw ApiFailure.bad("Valor de texto inválido: "+field);
        s=s.strip();if(s.length()>MAX.getOrDefault(field,20000))throw ApiFailure.bad("Texto demasiado largo: "+field);return s;
    }
    private Map<String,Object> normalized(Resource r,Map<String,Object> raw,Map<String,Object> old){
        if(!r.fields.containsAll(raw.keySet()))throw ApiFailure.bad("Campos no admitidos para este registro");
        Map<String,Object> d=new LinkedHashMap<>();for(String k:r.fields){Object v;
            if(raw.containsKey(k))v=raw.get(k);else if(old!=null)v=old.get(k);else if(k.equals("estado"))v=r.table.equals("peticiones")?"recibida":"solicitada";else v=DEFAULTS.get(k);
            d.put(k,normalize(k,v));}
        for(String k:r.required)if(d.get(k)==null)throw ApiFailure.bad("Complete "+k);
        for(String k:List.of("valor","valor_total","valor_fondo","sobrante_consignado")){if(d.get(k)==null)continue;boolean allowZero=k.equals("sobrante_consignado")||r.table.equals("solicitudes_presupuestales");if(money(d.get(k)).signum()<(allowZero?0:1))throw ApiFailure.bad("Importe no permitido: "+k);}
        return d;
    }
    Map<String,Object> get(Resource r,long id,AuthService.User u){require(u,r.module,false);return find(r,id,false);}
    List<Map<String,Object>> list(Resource r,Map<String,String> params,AuthService.User u){require(u,r.module,false);int skip=integer(params.getOrDefault("skip","0"),0,Integer.MAX_VALUE),limit=integer(params.getOrDefault("limit","100"),1,500);String sql="SELECT * FROM "+r.table+" WHERE 1=1";List<Object> args=new ArrayList<>();for(String k:r.filters){String v=params.get(k);if(v==null||v.isBlank())continue;sql+=" AND "+k+"=?";args.add(k.equals("vigencia")?integer(v,2000,2100):Set.of("caja_id","orden_id").contains(k)?identifier(v):v);}sql+=" ORDER BY id DESC LIMIT ? OFFSET ?";args.add(limit);args.add(skip);return db.queryForList(sql,args.toArray());}
    @Transactional public Map<String,Object> create(Resource r,Map<String,Object> raw,AuthService.User u){require(u,r.module,true);Map<String,Object> d=normalized(r,raw,null);validate(r,d,raw,null,u);d.put("created_by",u.username());String cols=String.join(",",d.keySet());String marks=String.join(",",Collections.nCopies(d.size(),"?"));Map<String,Object> out=db.queryForMap("INSERT INTO "+r.table+" ("+cols+") VALUES ("+marks+") RETURNING *",d.values().toArray());auth.audit(u.username(),"CREAR",r.table,id(out.get("id")),"Registro creado");return out;}
    @Transactional public Map<String,Object> update(Resource r,long id,Map<String,Object> raw,AuthService.User u){require(u,r.module,true);if(r.table.equals("reintegros_caja_menor"))throw new ApiFailure(405,"Los reintegros registrados no se modifican");Map<String,Object> old=find(r,id,true);Map<String,Object> d=normalized(r,raw,old);validate(r,d,raw,old,u);Map<String,Object> changes=new LinkedHashMap<>();for(String k:d.keySet())if(!eq(d.get(k),old.get(k)))changes.put(k,d.get(k));if(changes.isEmpty())return old;auth.audit(u.username(),"MODIFICAR",r.table,id,"Campos: "+String.join(", ",changes.keySet()));return apply(r,id,changes,u);}
    private Map<String,Object> apply(Resource r,long id,Map<String,Object> changes,AuthService.User u){changes.put("updated_by",u.username());List<Object> args=new ArrayList<>(changes.values());args.add(id);String assignments=String.join(",",changes.keySet().stream().map(k->k+"=?").toList());return db.queryForMap("UPDATE "+r.table+" SET "+assignments+",updated_at=CURRENT_TIMESTAMP WHERE id=? RETURNING *",args.toArray());}
    private BigDecimal sum(String table,String col,String foreign,long id,Long exclude){String sql="SELECT COALESCE(sum("+col+"),0) FROM "+table+" WHERE "+foreign+"=?";if(exclude!=null)return db.queryForObject(sql+" AND id<>?",BigDecimal.class,id,exclude);return db.queryForObject(sql,BigDecimal.class,id);}
    private BigDecimal spent(long cid,Long exclude){return sum("gastos_caja_menor","valor","caja_id",cid,exclude);}
    private BigDecimal replenished(long cid){return sum("reintegros_caja_menor","valor","caja_id",cid,null);}
    private BigDecimal balance(Map<String,Object> c){long cid=id(c.get("id"));return money(c.get("valor_fondo")).add(replenished(cid)).subtract(spent(cid,null));}
    private Map<String,Object> caja(long id,boolean lock){return find(resource("/cajas-menores"),id,lock);}
    private static void sameYear(Map<String,Object> c,LocalDate d){if(d.getYear()!=((Number)c.get("vigencia")).intValue())throw ApiFailure.bad("La fecha debe corresponder a la vigencia");}
    private void validate(Resource r,Map<String,Object> d,Map<String,Object> raw,Map<String,Object> old,AuthService.User u){
        switch(r.table){
            case "peticiones" -> {
                choice(d,"tipo_peticion",PET_TYPES);choice(d,"estado",PET_STATES);LocalDate start=date(d.get("fecha_ingreso"));String state=text(d.get("estado"));
                boolean recalc=d.get("fecha_vencimiento")==null||old!=null&&!raw.containsKey("fecha_vencimiento")&&List.of("fecha_ingreso","tipo_peticion","plazo_habil").stream().anyMatch(k->!eq(d.get(k),old.get(k)));
                if(recalc){Integer n=d.get("plazo_habil")!=null?(Integer)d.get("plazo_habil"):PLAZOS.get(text(d.get("tipo_peticion")));if(n==null)throw ApiFailure.bad("Para otro tipo de petición indique plazo o vencimiento");d.put("fecha_vencimiento",Calendario.diasHabiles(start,n));}
                if(Set.of("distribuida","en_tramite").contains(state)&&d.get("asignado_a")==null)throw ApiFailure.bad("Indique responsable de la petición");
                LocalDate end=date(d.get("fecha_vencimiento")),reply=date(d.get("fecha_respuesta"));if(end.isBefore(start)||reply!=null&&reply.isBefore(start))throw ApiFailure.bad("Las fechas no pueden ser anteriores al ingreso");if(state.equals("respondida")!=(reply!=null))throw ApiFailure.bad("La fecha de respuesta requiere estado respondida y viceversa");
            }
            case "cajas_menores" -> {
                if(old==null){role(u,"auxiliar_administrativo","abogado_delegado","secretario");if(d.get("sobrante_consignado")!=null)throw ApiFailure.bad("El sobrante se registra al cierre");}
                else{String state=text(old.get("estado"));if(state.equals("cierre"))throw ApiFailure.conflict("La caja está cerrada");if(!eq(d.get("vigencia"),old.get("vigencia")))throw ApiFailure.bad("No se puede cambiar la vigencia");if(!eq(d.get("valor_fondo"),old.get("valor_fondo"))&&(!state.equals("apertura")||spent(id(old.get("id")),null).signum()>0))throw ApiFailure.conflict("El fondo solo se modifica antes de registrar gastos");if(!eq(d.get("sobrante_consignado"),old.get("sobrante_consignado"))){role(u,"auxiliar_administrativo","apoyo_financiero");if(!state.equals("reintegro"))throw ApiFailure.conflict("Registre el sobrante en la etapa de reintegro/cierre");}}
            }
            case "gastos_caja_menor" -> {
                choice(d,"estado_revision",REV_STATES);long cid=id(d.get("caja_id"));if(old!=null&&cid!=id(old.get("caja_id")))throw ApiFailure.bad("No puede trasladar el gasto a otra caja");Map<String,Object> c=caja(cid,true);String state=text(c.get("estado"));sameYear(c,date(d.get("fecha")));
                if(old==null){role(u,"auxiliar_administrativo","secretario");if(!Set.of("apertura","compras","relacion_gastos").contains(state))throw ApiFailure.conflict("No se pueden crear gastos en esta etapa");if(!d.get("estado_revision").equals("pendiente"))throw ApiFailure.bad("El gasto nuevo queda pendiente de revisión");d.put("ciclo",c.get("ciclo"));}
                else{if(!Set.of("apertura","compras","relacion_gastos","revision_juridica").contains(state)||!eq(c.get("ciclo"),old.get("ciclo")))throw ApiFailure.conflict("El gasto pertenece a una etapa o ciclo cerrado");Set<String> rev=Set.of("estado_revision","observacion_revision");Set<String> changed=new HashSet<>();for(String k:r.fields)if(!eq(d.get(k),old.get(k)))changed.add(k);if(changed.stream().anyMatch(rev::contains)){role(u,"abogado_delegado");if(!state.equals("revision_juridica"))throw ApiFailure.conflict("Registre la revisión jurídica en su etapa");}if(changed.stream().anyMatch(k->!rev.contains(k))){role(u,"auxiliar_administrativo","secretario");d.put("estado_revision","pendiente");d.put("observacion_revision",null);}}
                BigDecimal total=spent(cid,old==null?null:id(old.get("id"))).add(money(d.get("valor")));if(total.compareTo(money(c.get("valor_fondo")).add(replenished(cid)))>0)throw ApiFailure.bad("El gasto excede el saldo de caja menor");
            }
            case "reintegros_caja_menor" -> {
                role(u,"auxiliar_administrativo","apoyo_financiero");long cid=id(d.get("caja_id"));Map<String,Object> c=caja(cid,true);sameYear(c,date(d.get("fecha")));if(!c.get("estado").equals("reintegro")||c.get("sobrante_consignado")!=null)throw ApiFailure.conflict("Registre el reintegro después de Control Interno y antes del cierre");if(money(d.get("valor")).compareTo(spent(cid,null).subtract(replenished(cid)))>0)throw ApiFailure.bad("El reintegro excede el gasto neto");d.put("ciclo",c.get("ciclo"));
            }
            case "solicitudes_presupuestales" -> {choice(d,"tipo",BUDGET_TYPES);choice(d,"estado",BUDGET_STATES);if(old!=null){BigDecimal total=sum("descuentos","valor","orden_id",id(old.get("id")),null);if(total.signum()>0&&!d.get("tipo").equals("orden_pago"))throw ApiFailure.conflict("La orden tiene descuentos asociados");if(d.get("valor")!=null&&total.compareTo(money(d.get("valor")))>0)throw ApiFailure.bad("Los descuentos superan el valor de la orden");}}
            case "descuentos" -> {choice(d,"tipo",DISCOUNT_TYPES);long oid=id(d.get("orden_id"));Map<String,Object> order=find(resource("/presupuesto/solicitudes"),oid,true);if(!order.get("tipo").equals("orden_pago"))throw ApiFailure.bad("Seleccione una orden de pago válida");BigDecimal total=sum("descuentos","valor","orden_id",oid,old==null?null:id(old.get("id"))).add(money(d.get("valor")));if(order.get("valor")!=null&&total.compareTo(money(order.get("valor")))>0)throw ApiFailure.bad("Los descuentos superan el valor de la orden");}
            case "convenios" -> {if(text(d.get("nit")).length()<5)throw ApiFailure.bad("Indique el NIT completo");if(old!=null){if(old.get("estado").equals("liquidado"))throw ApiFailure.conflict("El convenio ya está liquidado");LocalDate send=date(old.get("fecha_envio_contaduria"));if(send!=null&&date(d.get("fecha_inicio")).isAfter(send))throw ApiFailure.bad("Fecha de inicio posterior a la remisión");}}
            default -> throw ApiFailure.missing();
        }
    }
    List<Map<String,Object>> seguimiento(AuthService.User u){require(u,"peticiones",false);LocalDate today=Calendario.hoy();List<Map<String,Object>> rows=db.queryForList("SELECT id,numero_radicado AS radicado,peticionario,asignado_a,estado,fecha_vencimiento AS vence FROM peticiones WHERE estado<>'respondida' ORDER BY fecha_vencimiento");for(Map<String,Object> row:rows){LocalDate end=date(row.get("vence"));row.put("dias_restantes",ChronoUnit.DAYS.between(today,end));row.put("vencida",end.isBefore(today));}return rows;}
    Map<String,Object> cajaResumen(long cid,AuthService.User u){require(u,"caja_menor",false);Map<String,Object> c=caja(cid,false);Map<String,Object> out=new LinkedHashMap<>();for(String k:List.of("id","vigencia","estado","ciclo","sobrante_consignado"))out.put(k,c.get(k));out.put("fondo",c.get("valor_fondo"));out.put("gastado",spent(cid,null));out.put("reintegrado",replenished(cid));out.put("saldo",balance(c).subtract(zero(c.get("sobrante_consignado"))));return out;}
    List<Map<String,Object>> cajaHistorial(long cid,AuthService.User u){require(u,"caja_menor",false);caja(cid,false);return db.queryForList("SELECT ts,usuario,accion,detalle FROM auditoria WHERE entidad='cajas_menores' AND entidad_id=? ORDER BY id DESC",cid);}
    record Event(LocalDate fecha,String responsable,String referencia) {}
    private Event event(Map<String,Object> raw,AuthService.User u){raw=raw==null?Map.of():raw;AuthService.fields(raw,Set.of("fecha","responsable","referencia"));LocalDate d=raw.get("fecha")==null?Calendario.hoy():date(raw.get("fecha"));String person=AuthService.string(raw,"responsable",150,false);String ref=AuthService.string(raw,"referencia",300,false);return new Event(d,person==null?u.fullName():person,ref==null?"Sin referencia":ref);}
    private String eventDetail(String before,String after,Event e){return before+" -> "+after+" | fecha informada: "+e.fecha+" | responsable: "+e.responsable+" | referencia: "+e.referencia;}
    @Transactional public Map<String,Object> cajaAction(long cid,String action,Map<String,Object> raw,AuthService.User u){require(u,"caja_menor",true);Map<String,Object> c=caja(cid,true);String before=text(c.get("estado"));Event e=event(raw,u);sameYear(c,e.fecha);String next;Map<String,Object> changes=new LinkedHashMap<>();if(action.equals("nuevo-ciclo")){role(u,"auxiliar_administrativo","apoyo_financiero");if(!before.equals("reintegro")||c.get("sobrante_consignado")!=null)throw ApiFailure.conflict("Solo se abre un ciclo desde reintegro, antes de consignar el sobrante");next="compras";changes.put("ciclo",((Number)c.get("ciclo")).intValue()+1);}else{int i=ETAPAS.indexOf(before);if(i<0||i==ETAPAS.size()-1)throw ApiFailure.conflict("La caja menor está cerrada");next=ETAPAS.get(i+1);switch(next){case "compras"->role(u,"auxiliar_administrativo","abogado_delegado","secretario");case "relacion_gastos"->role(u,"auxiliar_administrativo");case "revision_juridica"->role(u,"auxiliar_administrativo","abogado_delegado");case "firma"->role(u,"abogado_delegado");case "control_interno"->role(u,"secretario");case "reintegro","cierre"->role(u,"auxiliar_administrativo","apoyo_financiero");default->throw ApiFailure.conflict("Etapa inválida");}if(next.equals("compras")&&c.get("resolucion")==null)throw ApiFailure.conflict("Registre la resolución de apertura");if(next.equals("firma")&&db.queryForObject("SELECT count(*) FROM gastos_caja_menor WHERE caja_id=? AND estado_revision<>'aprobado'",Long.class,cid)>0)throw ApiFailure.conflict("Existen gastos sin revisión aprobada");if(next.equals("cierre")&&(c.get("sobrante_consignado")==null||money(c.get("sobrante_consignado")).compareTo(balance(c))!=0))throw ApiFailure.conflict("El sobrante consignado debe dejar el fondo en $0,00");}
        changes.put("estado",next);apply(resource("/cajas-menores"),cid,changes,u);auth.audit(u.username(),"CAMBIO_ESTADO","cajas_menores",cid,eventDetail(before,next,e));return Map.of("id",cid,"estado",next);
    }
    private boolean docExists(long id,String type){return db.queryForObject("SELECT count(*) FROM documentos WHERE entidad='convenio' AND entidad_id=? AND tipo=?",Long.class,id,type)>0;}
    @Transactional public Map<String,Object> convenioAction(long cid,String action,Map<String,Object> raw,AuthService.User u){require(u,"convenios",true);Resource r=resource("/convenios");Map<String,Object> c=find(r,cid,true);String before=text(c.get("estado"));Event e=event(raw,u);Map<String,Object> d=new LinkedHashMap<>();String after;String auditAction="CAMBIO_ESTADO";switch(action){case "enviar-contaduria"->{if(!before.equals("registrado"))throw ApiFailure.conflict("El convenio ya fue remitido");if(e.fecha.isBefore(date(c.get("fecha_inicio"))))throw ApiFailure.bad("Fecha anterior al inicio");if(!docExists(cid,"contrato"))throw ApiFailure.conflict("Adjunte el contrato o convenio");after="enviado_contaduria";d.put("estado",after);d.put("fecha_envio_contaduria",e.fecha);}case "liquidar"->{if(!before.equals("enviado_contaduria"))throw ApiFailure.conflict("Registre primero la remisión a Contaduría");if(e.fecha.isBefore(date(c.get("fecha_envio_contaduria"))))throw ApiFailure.bad("Fecha anterior a la remisión");if(!docExists(cid,"acta_liquidacion"))throw ApiFailure.conflict("Adjunte el acta de liquidación");after="liquidado";d.put("estado",after);d.put("fecha_liquidacion",e.fecha);}case "enviar-liquidacion"->{if(!before.equals("liquidado")||c.get("fecha_envio_liquidacion")!=null)throw ApiFailure.conflict("Requiere una liquidación aún no remitida");if(e.fecha.isBefore(date(c.get("fecha_liquidacion"))))throw ApiFailure.bad("Fecha anterior a la liquidación");after="acta remitida";d.put("fecha_envio_liquidacion",e.fecha);auditAction="REMISION_LIQUIDACION";}default->throw ApiFailure.missing();}Map<String,Object> result=apply(r,cid,d,u);auth.audit(u.username(),auditAction,"convenios",cid,eventDetail(before,after,e));return result;}
    private Map<String,Object> counts(String table){Map<String,Object> out=new LinkedHashMap<>();for(Map<String,Object> x:db.queryForList("SELECT estado,count(*) AS n FROM "+table+" GROUP BY estado ORDER BY estado"))out.put(text(x.get("estado")),x.get("n"));return out;}
    Map<String,Object> panel(AuthService.User u){Map<String,Object> m=new LinkedHashMap<>();if(AuthService.allowed(u,"peticiones",false))m.put("peticiones",Map.of("por_estado",counts("peticiones"),"vencidas",db.queryForObject("SELECT count(*) FROM peticiones WHERE estado<>'respondida' AND fecha_vencimiento<?",Long.class,Calendario.hoy())));if(AuthService.allowed(u,"caja_menor",false)){m.put("cajas_menores",counts("cajas_menores"));m.put("gastos_pendientes_revision",db.queryForObject("SELECT count(*) FROM gastos_caja_menor WHERE estado_revision='pendiente'",Long.class));}if(AuthService.allowed(u,"presupuesto",false))m.put("presupuesto",counts("solicitudes_presupuestales"));if(AuthService.allowed(u,"convenios",false)){m.put("convenios",counts("convenios"));m.put("convenios_valor_total",db.queryForObject("SELECT COALESCE(sum(valor_total),0) FROM convenios",BigDecimal.class));}return m;}
    List<Map<String,Object>> reportRows(Resource r,AuthService.User u){require(u,r.module,false);return db.queryForList("SELECT * FROM "+r.table+" ORDER BY id");}
}
